import{z as o,x as l,o as A,c as d,q as B,j as i,D as a,d as e,s as r,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"数据获取与审计","description":"","frontmatter":{"title":"数据获取与审计","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/data-acquisition-audit.md","filePath":"quant/data-acquisition-audit.md","lastUpdated":1791413859000}'),p={name:"quant/data-acquisition-audit.md"};function u(C,E,F,h,D,f){const n=l("Mermaid");return A(),d("div",null,[E[2]||(E[2]=B('<h1 id="数据获取与审计" tabindex="-1">数据获取与审计 <a class="header-anchor" href="#数据获取与审计" aria-label="Permalink to &quot;数据获取与审计&quot;">​</a></h1><div class="epigraph"><p>回测里最贵的错误不是算错，而是把「数据存在」当成了「当时已知」。</p><footer>—— 据时点数据库（CRSP / Compustat 点时快照）与 SEC Reg FD（2000）的实务口径整理</footer></div><p><a href="/quant/hypothesis-preregistration">上一课</a>把假设合同签在动手之前，其中 universe、排除规则与成本假设都要落到具体数据上。本课是「假设与数据」单元的最后一道闸：让数据配得上合同。前视与幸存者的理论分别在<a href="/quant/look-ahead-bias">前视偏差</a>与<a href="/quant/survivorship-bias">幸存者偏差</a>讲过；本课不重讲理论，把它们用成一张可执行的审计清单。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>注册文档写「公告后六十个交易日」，数据集给你的字段是报告期末日；写「当时可交易的股票」，数据集给的是今天还活着的列表；写「财报数字」，供应商给的是修正过三轮的最新值。三种错都发生在获取这一步，且全都不报错——数字看起来都像样。点时逻辑在<a href="/quant/point-in-time">时点基本面</a>与 <a href="/quant/pit-fundamentals">Point-in-time 基本面</a>里已经立起：每个字段带两枚时间戳，事件归属期与信息可得日。本课的问题是：拿到任何一份新数据，怎么在动手前系统地确认它经得起这两枚时间戳的拷问。</p><p><span class="marginnote">「两枚时间戳」翻译成大白话：一条财报数据既要说清它描述的是哪个季度（事件期），又要说清你最早在哪一天能查到它（可得日）。回测在 \\(d\\) 日做决策时，只有可得日 \\(\\le d\\) 的记录才算「当时已知」，其余一律不许进信号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>审计清单五项，按序过。<strong>一，时点性</strong>：每个用于构造信号的字段有无「可得日」；回测按可得日做 as-of 对齐，做法见<a href="/quant/pit-alignment">点-in-time 基本面对齐</a>与<a href="/quant/filing-lag-available-date">财报滞后与可用日期</a>。没有可得日的字段，标记不可用或只用于截面比较。<strong>二，覆盖与 universe</strong>：退市股在不在面板里；指数成分有无历史（<a href="/quant/index-constituents-history">指数成分历史</a>）；起止日期画分布，别只看总行数。<strong>三，公司行动</strong>：复权方式与信号计算一致（<a href="/quant/corporate-actions">分红、拆股与复权</a>），股本变动有历史版本。<strong>四，修正与重述</strong>：拿到的是初值还是最新值（<a href="/quant/fundamentals-restatements">基本面数据与重述</a>）；有 vintage 快照用快照，没有就把修正字段整体降权。<strong>五，对账</strong>：行数、唯一键、重复时间戳、校验和，抽样与第二来源比对（选择口径见<a href="/quant/data-vendors">数据供应商对照</a>）。</p><p>审计报告一页，附在注册文档后：每项过或不过，不过时给出降级用法。</p><p><span class="marginnote">SEC 对大型加速申报人的期限：10-K 为期末后 60 天，10-Q 为 40 天。把报告期末日当公告日用，等于让 PEAD 回测在公告之前就开始持有——信号的头几十个交易日是幻觉。</span></p><h3 id="审计改变结论的例子" tabindex="-1">审计改变结论的例子 <a class="header-anchor" href="#审计改变结论的例子" aria-label="Permalink to &quot;审计改变结论的例子&quot;">​</a></h3><p>同一个 SUE 信号：按期末日对齐，回测 IC 漂亮；换可得日对齐，公告前那段的「信号」消失，只剩公告后的真实漂移。差异不是模型调好了，而是审计把一段不存在的可交易期从结果里删掉了。</p>',12)),(A(),i(s,null,{default:a(()=>[r(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20QE%5B%22%E5%AD%A3%E5%BA%A6%E7%BB%93%E6%9D%9F%EF%BC%88%E6%8A%A5%E5%91%8A%E6%9C%9F%E6%9C%AB%E6%97%A5%EF%BC%89%22%5D%20--%3E%20GAP%5B%22%E7%9C%9F%E5%AE%9E%E4%B8%96%E7%95%8C%EF%BC%9A%E7%AD%89%E7%BA%A6%2040%20%E5%88%B0%2060%20%E5%A4%A9%E6%89%8D%E5%85%AC%E5%91%8A%22%5D%0A%20%20GAP%20--%3E%20ANN%5B%22%E5%85%AC%E5%91%8A%E6%97%A5%20%3D%20%E4%BF%A1%E6%81%AF%E5%8F%AF%E5%BE%97%E6%97%A5%22%5D%0A%20%20QE%20--%3E%7C%22%E6%8C%89%E6%9C%9F%E6%9C%AB%E6%97%A5%E5%AF%B9%E9%BD%90%22%7C%20LEAK%5B%22%E5%9B%9E%E6%B5%8B%E6%8F%90%E5%89%8D%E5%BB%BA%E4%BB%93%EF%BC%9A%E5%B9%BB%E8%A7%89%E6%94%B6%E7%9B%8A%E7%AA%97%E5%8F%A3%22%5D%0A%20%20ANN%20--%3E%7C%22%E6%8C%89%E5%8F%AF%E5%BE%97%E6%97%A5%E5%AF%B9%E9%BD%90%22%7C%20OK%5B%22%E5%85%AC%E5%91%8A%E5%90%8E%E6%89%8D%E5%BB%BA%E4%BB%93%EF%BC%9A%E7%9C%9F%E5%AE%9E%E5%8F%AF%E4%BA%A4%E6%98%93%E7%AA%97%E5%8F%A3%22%5D%0A%20%20LEAK%20--%3E%20DIFF%5B%22%E4%B8%A4%E7%89%88%E5%9B%9E%E6%B5%8B%E7%9A%84%E5%B7%AE%E5%80%BC%E5%B0%B1%E6%98%AF%E5%89%8D%E8%A7%86%E6%B3%84%E6%BC%8F%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("p",null,[t("span",{class:"marginnote"},"初学者容易以为把数字放进报告期那一行只是「排序习惯」。实际上对齐日决定了信号从哪一天起才可交易：按期末日对齐，回测在公告前就开始「持有」，这段收益现实中根本拿不到；换成可得日对齐，幻觉窗口整体消失，剩下的才是真实可得的信号。")],-1)),E[4]||(E[4]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),(A(),i(s,null,{default:a(()=>[r(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E4%BE%9B%E5%BA%94%E5%95%86%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20TS%7B%22%E4%B8%A4%E6%9E%9A%E6%97%B6%E9%97%B4%E6%88%B3%EF%BC%9A%E4%BA%8B%E4%BB%B6%E6%9C%9F%20%2B%20%E5%8F%AF%E5%BE%97%E6%97%A5%22%7D%0A%20%20TS%20--%3E%7C%E7%BC%BA%E5%A4%B1%7C%20FLAG%5B%22%E6%A0%87%E8%AE%B0%E9%99%8D%E7%BA%A7%E6%88%96%E5%BC%83%E7%94%A8%22%5D%0A%20%20TS%20--%3E%7C%E9%BD%90%7C%20ASOF%5B%22%E6%8C%89%E5%8F%AF%E5%BE%97%E6%97%A5%20as-of%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20ASOF%20--%3E%20COV%7B%22%E8%A6%86%E7%9B%96%E5%AE%A1%E8%AE%A1%EF%BC%9A%E9%80%80%E5%B8%82%20%2B%20%E6%88%90%E5%88%86%E5%8E%86%E5%8F%B2%22%7D%0A%20%20COV%20--%3E%20CORP%7B%22%E5%85%AC%E5%8F%B8%E8%A1%8C%E5%8A%A8%E4%B8%8E%E5%A4%8D%E6%9D%83%E4%B8%80%E8%87%B4%22%7D%0A%20%20CORP%20--%3E%20REV%7B%22%E4%BF%AE%E6%AD%A3%E4%B8%8E%20vintage%20%E7%AD%96%E7%95%A5%22%7D%0A%20%20REV%20--%3E%20RECON%5B%22%E5%AF%B9%E8%B4%A6%E4%B8%8E%E6%8A%BD%E6%A0%B7%E6%AF%94%E5%AF%B9%22%5D%0A%20%20RECON%20--%3E%20PANEL%5B%22%E8%BF%9B%E5%85%A5%E5%88%86%E6%9E%90%E7%9A%84%E5%88%86%E6%9E%90%E9%9D%A2%E6%9D%BF%22%5D%0A%20%20RECON%20--%3E%20FAIL%5B%22%E5%AE%A1%E8%AE%A1%E6%8A%A5%E5%91%8A%EF%BC%9A%E4%B8%8D%E8%BF%87%E9%A1%B9%E4%B8%8E%E9%99%8D%E7%BA%A7%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p>审计守三件事。守<strong>知识集合的单调性</strong>：\\(t\\) 日的决策只能用 \\(t\\) 日前已公开的信息——理论是前视偏差，清单把它落到每一列。守<strong>宇宙的完整性</strong>：面板里少一只退市股，等于给每个截面的多头腿做了一次正向筛选。守<strong>值的代际</strong>：用修订值做信号、用初值算漂移，两条线一混，剩下的差异全是数据工程噪声。这三件事没有一件能靠统计事后修正——它们发生在似然函数写成之前，这正是审计排在评估前面的原因。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>审计只保证「错误方向已知且偏保守」，不保证数据正确：缺失就是缺失，回填得再平滑也不产生信息（<a href="/quant/alt-data-backfill-bias">回填偏差</a>）。vintage 数据贵，很多研究只能用最新值加修正标记，降级用法要写进审计报告，让读者知道结论带多少水分。审计绑定数据版本：供应商一升级，清单重跑。最后，清单不能替代抽查——每季度抽几只股票手工走一遍生命周期（上市、公告、拆股、退市），人眼比脚本更能发现「字段都在但语义不对」的错。</p><p><span class="marginnote">数字感受覆盖缺失：假设每年约 4% 的公司退市或被并购，\\(0.96^{10}\\approx0.66\\)，十年下来约三分之一的样本消失了。若面板只留活到今天的股票，等于每个截面都先删掉失败者再选股，回测收益被系统性抬高，而且全程没有任何报错。同理，「vintage 快照」就是给数据库每天拍一张底片：调的是当时的原始值，不是被后来几轮修订改过的「最终答案」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>数据审计五项：时点性、覆盖与 universe、公司行动、修正与重述、对账。</li><li>时点性的核心是两枚时间戳：事件归属期与信息可得日；回测按可得日对齐。</li><li>审计错误发生在似然函数写成之前，统计修正救不回来。</li><li>审计报告一页入台账，降级用法显式化；数据版本变更即重审。</li><li>出处：CRSP / Compustat 点时数据库实务口径；SEC Reg FD (2000) 与申报期限规则；点时与幸存者理论见站内对应课。</li></ul>',6))])}const c=o(p,[["render",u]]);export{g as __pageData,c as default};
